from collections import defaultdict
from datetime import datetime, timezone
from f.db.cratedb import CrateConnector

KEY=('media_type','media_tmdb_id','country_code','streaming_service_id','streaming_type')
LO=1792195200000
HI=1792800000000

def key(r):return tuple(r[k] for k in KEY)

def main():
    c=CrateConnector()
    try:
        # Filter each side by indexed dates, join in memory instead of a broad database self-join.
        closed=c.select('SELECT '+','.join(KEY)+',observed_at,dropped_on,dropped_precision,created_at,updated_at,appeared_source FROM availability_history WHERE dropped_on >= ? AND dropped_on < ? LIMIT 1000001',(LO,HI))
        if len(closed)>1000000:raise RuntimeError('Closed-row bound exceeded')
        by_key=defaultdict(list)
        for r in closed:by_key[key(r)].append(r)
        count_closed=len(closed)
        del closed
        opened=c.select('SELECT * FROM availability_history WHERE observed_at >= ? AND observed_at < ? LIMIT 300001',(LO,HI))
        if len(opened)>300000:raise RuntimeError('Opened-row bound exceeded')
        returns=[]
        for r in opened:
            prior=[old for old in by_key.get(key(r),[]) if old['observed_at']<r['observed_at'] and old['dropped_on']<=r['observed_at']]
            if prior:
                old=max(prior,key=lambda x:x['observed_at'])
                returns.append(r|{'prior_'+k:v for k,v in old.items() if k not in KEY})
        print('Closed',count_closed,'Opened',len(opened),'Return stays',len(returns),flush=True)
        del by_key,opened
        # Current re-created incarnations: fetch current new rows, then only the backup keys of those titles.
        current=c.select("SELECT "+','.join(KEY)+",created_at,updated_at FROM streaming_availability WHERE streaming_type IN ('flatrate','free','ads') AND created_at >= ? AND created_at < ? LIMIT 300001",(LO,HI))
        if len(current)>300000:raise RuntimeError('Current-row bound exceeded')
        current_by_key={key(r):r for r in current}
        recreated={}
        for media in ('movie','show'):
            ids=sorted({r['media_tmdb_id'] for r in current if r['media_type']==media})
            for start in range(0,len(ids),200):
                prior=c.select("SELECT "+','.join(KEY)+",observed_at,created_at,dropped_on,appeared_source FROM availability_history_before_682 WHERE media_type = ? AND media_tmdb_id = ANY(?) LIMIT 1000001",(media,ids[start:start+200]))
                if len(prior)>1000000:raise RuntimeError('Backup-row bound exceeded')
                for r in prior:
                    a=current_by_key.get(key(r))
                    if a and r['appeared_source']=='backfill' and a['created_at']>r['created_at'] and a['created_at']>r['observed_at']:
                        recreated[key(r)]=a|{'prior_'+k:v for k,v in r.items() if k not in KEY}
        return {'measured_at':datetime.now(timezone.utc).isoformat(),'closed_stays':count_closed,'history_returns':returns,'current_new_offer_rows':len(current),'backup_recreated':list(recreated.values())}
    finally:c.disconnect()
